  // Better Auth tools (agents.mcp.exposeAuthTools) live on /auth/v<n>/…, outside
  // the API mount, so they are dispatched as-is too.
  const prefixed = interpolated.startsWith('/api/v1/') || interpolated === '/api/v1' || AUTH_SURFACE_PATH.test(interpolated)
    ? interpolated
    : '/api/v1' + interpolated;
  const url = new URL(prefixed, origin);
  for (const q of tool._queryParams) {
    const v = args[q];
    if (v !== undefined && v !== null) url.searchParams.set(q, String(v));
  }

  // Bearer-only on the MCP surface — forward Authorization and nothing else.
  // Cookies aren't accepted on /mcp (no CSRF surface, no browser callers),
  // and x-api-key is not forwarded. Four Bearer flavors land on this header:
  //   • BA session token (via the bearer plugin)
  //   • OAuth access token (via oauthProvider)
  //   • Agent JWT (via @better-auth/agent-auth, after agent JWT verification)
  //   • Prefixed API key (the auth middleware's key lane; scopes checked here)
  // The inner Hono middleware chain resolves whichever flavor arrives.
