  const auth = parent.headers.get('Authorization');
  if (auth) headers.set('Authorization', auth);

  // POST / PUT / PATCH always send JSON, even when the operation declares no
  // body fields (input: z.object({}) with path params only). The route's
  // body validator expects an object; sending nothing makes it see undefined
  // and 400 every call, while the same request over REST with {} succeeds.
  // DELETE sends JSON only when the operation declares body fields
  // (DELETE /<resource>/batch reads { ids, options }); single-record DELETE,
  // GET and HEAD stay body-less.
  const method = tool._method.toUpperCase();
  const fields = tool._bodyFields ?? [];
  const carriesBody =
    method === 'POST' || method === 'PUT' || method === 'PATCH' ||
    (method === 'DELETE' && fields.length > 0);
